import re, random, bisect

def assemble(retrieval, prefix, budget_tokens, tok_len):
    """Right-to-left packing anchored at cursor: prefix last-truncated,
    snippets dropped whole from last to first."""
    p_tok = tok_len(prefix)
    keep = list(retrieval)
    while keep and p_tok + sum(tok_len(s) for s in keep) > budget_tokens:
        keep.pop()                      # drop last retrieval snippet
    body = "\n\n".join(keep)
    avail = budget_tokens - sum(tok_len(s) for s in keep)
    if p_tok > avail:                   # left-clip prefix, keep cursor at end
        words = prefix.split(" ")
        while words and tok_len(" ".join(words)) > avail:
            words = words[1:]
        prefix = " ".join(words)
    trunc = (len(keep) < len(retrieval)) or p_tok + sum(tok_len(s) for s in keep) > budget_tokens and False
    return body, prefix

def postprocess(raw, model):
    """Detokenizer parity spec: (1) caller decoded with skip_special_tokens=True
    (2) strip exactly one leading space (Llama SPM artifact) for BOTH models
    (3) cut at first newline  (4) strip trailing whitespace."""
    s = raw
    if s.startswith(" "): s = s[1:]
    s = s.split("\n", 1)[0]
    return s.rstrip()

def nws(s): return re.sub(r"\s+", "", s)

def em(h, r): return int(nws(h) == nws(r))

def lev(a, b):
    if len(a) < len(b): a, b = b, a
    prev = list(range(len(b)+1))
    for i, ca in enumerate(a, 1):
        cur = [i]
        for j, cb in enumerate(b, 1):
            cur.append(min(prev[j]+1, cur[j-1]+1, prev[j-1] + (ca != cb)))
        prev = cur
    return prev[-1]

def es(h, r):
    a, b = nws(h), nws(r)
    m = max(len(a), len(b))
    return 1.0 if m == 0 else 1.0 - lev(a, b)/m

